function filter$saveReportPrint(p){
  this.constructor(p);
}
filter$saveReportPrint.prototype = new DirEvent();
filter$saveReportPrint.prototype.beforeInit = function(){
  var p = this._dir;
  p.options.fis = {};
  var k, i, fs, d = p.options._fields, fs = d.grids.grid[0].fields.field, field = p.field("field", 0);
  for (i = 0; i < fs.length; i++) {
      field.viewInfo.options.option.push({ val: fs[i].name, text: { lan: fs[i].text.lan } })
      p.options.fis[fs[i].name] = fs[i];
  }
}
filter$saveReportPrint.prototype.afterInit = function(){
  var i, p = this._dir;
}
filter$saveReportPrint.prototype.commandActionClick = function (action, id) {
  var ev = this, p = this._dir, o = p.jObject('xid'), v = o.fval(), pa = p.options.parent;
  switch (action) {
    case "btn_delete":
      if (v == '') {o.focus(); return; }
      $.question(p.msg("VoucherDelete"), $.msg.get("DeleteTitle"), p, function (q, vq) {
          q._close();
          if (vq) {
            p.request('DeleteForm', '', ['xid', ['controller', 'C', pa.options.controller]], function(pp, d, run) {
              if (run) {
                o.find("[value='" + v + "']").remove();
                ev.formFieldValueChange(o, 'xid', '');
                $.clearClientCache();
                o.focus();
              }
            });
          }
      });
      break;
    case "btn_copy":
      if (v == '') {o.focus(); return; }
      p.valForm('xid', '');
      p.valForm('form_type', '0');
      p.options.action = 'NEW';
      break;
    default:
      break;
  }
}
filter$saveReportPrint.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir, pa = p.options.parent;
  switch (cF){
    case 'xid':
      if (v == '') p.options.action = 'NEW';
      else p.options.action = 'EDIT';
      p.request('GetForm', '', ['xid', ['controller', 'C', pa.options.controller]]);
      p.reloadGrid(0, [['xid', 'C', v], ['action', 'C', p.options.action]]);
      break;
    default:
      break;
  }
}
filter$saveReportPrint.prototype.formActionChange = function (action, m, run) {
  var p = this._dir, pa = p.options.parent;
  switch (action) {
    case 'BeforeInsert':
      m.val('controller', 'C', pa.options.controller, 'FIELD')
      m.val('xid', 'C', p.valForm('xid'));
      break;
    case 'BeforeUpdate':
      m.val('controller', 'C', pa.options.controller, 'FIELD');
      m.val('xid', 'C', p.valForm('xid'));
      break;
    case 'AfterUpdate':
    case 'AfterInsert':
      if (run) {
        $.showToast(p.msg('mustReload'));
        $.clearClientCache();
      }
      return true;
      break;
    default:
      break;
  }
  return true;
}
filter$saveReportPrint.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir, g = p.grid(gindex), dt = g.data;
  if (action == 'AfterAddRow') {
    filter$saveReportPrintSetDefaultColumnValue(p, r);
  }
  return true;
}
filter$saveReportPrint.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
    case 'field':
      filter$saveReportPrintSetDefaultColumnValue(p, r);
      break;
    default:
      break;
  }
}
function filter$saveReportPrintSetDefaultColumnValue(p, r) {
  var g = p.grid(0), dt = g.data, cF = dt.val(r, 'field'), fi = p.options.fis[cF];
  p.valGrid(r, 'header', 0, fi.text.v.toUpperCase());
  p.valGrid(r, 'header2', 0, fi.text.e.toUpperCase());
  p.valGrid(r, 'width', 0, fi.width);
  p.valGrid(r, 'format', 0, fi.format);
  p.valGrid(r, 'data_type', 0, fi.dataType);
  if (fi.dataType == 'I') p.valGrid(r, 'format', 0, "-1");
  if (fi.dataType == 'N' || fi.dataType == 'I') p.valGrid(r, 'align', 0, 'R');
  else if (fi.dataType == 'D') p.valGrid(r, 'align', 0, 'C');
  else p.valGrid(r, 'align', 0, 'L');
}

beforesave.text:
if 0 = (select count(1) from @sysreportprint2) begin select '$columnNotBlank' as message return end if exists (select 1 from @sysreportprint2 group by field having count(1) > 1) begin select '$columnDuplicate' as message return end if @form_type = 1 and @@admin = 0 begin select '$notSaveCommonForm' as message return end
if @action = 'NEW' select @user_id = @@userId, @id = isnull(max(id), 0) + 1 from sysreportprint where controller = @controller --and user_id = @@userId else select @user_id = left(@xid, charindex('_', @xid) - 1), @id = right(@xid, len(@xid) - charindex('_', @xid))
update @sysreportprint2 set user_id = @user_id, id = @id, controller = @controller, field2 = field
